-- Guest Hub H10b (18 Nov 2026, Ahmed — DECISIONS.md 2026-11-18 «Guest Hub H10»): the cards are filtered by the adults only
-- (his decision of 23 Oct 2026: children are not counted and have no limit per room). The bank only — the correction of
-- h10-11 and the new case h10-27 (two adults and five children asking for a two-bedroom suite). Generated by
-- scripts/hub-h10b-migration.mjs — never edited once applied (CLAUDE.md §12). Every UPDATE carries a WHERE.

update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": ["ask"]},{"outcome": "quote", "cards": [1,3]}]}'::jsonb
 where key = 'h10-11' and expect = '{"action": "conversation", "steps": [{"outcome": ["ask"]},{"outcome": "handoff", "must_include": ["أكثر من غرفة"], "must_not_include": ["غرفة بسرير كينج", "غرفة سريرين"]}]}'::jsonb;
do $$
declare v_sort integer := coalesce((select max(sort) + 1 from public.hub_test_items), 0);
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($h10b_bank$[{"key":"h10-27","unit":"airport-road","language":"ar","messages":["أبغى شقة بغرفتي نوم وصالة من 10 ديسمبر إلى 14 ديسمبر، أنا وزوجتي و5 أطفال","بدون إفطار"],"expect":{"action":"conversation","steps":[{"outcome":["ask"]},{"outcome":"quote","cards":[1,3],"must_include":["بغرفتي نوم"]}]},"note":"bd27baf4 paraphrased (Ahmed, 18 Nov 2026): two adults and five children asking for a two-bedroom suite — the named type comes first; children never counted","tags":["conversation","h10","h10b","capacity"],"context":{}}]$h10b_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
